```kotlin
package example

import example.dto.BookView
import java.math.BigDecimal
import org.babyfish.jimmer.Page
import org.babyfish.jimmer.sql.kt.KSqlClient
import org.babyfish.jimmer.sql.kt.ast.expression.*
import org.babyfish.jimmer.sql.kt.ast.table.*

object CanaryKotlin {

    fun increasePrice(
        sql: KSqlClient,
        id: Long,
        expectedVersion: Int,
        delta: BigDecimal
    ): Boolean {
        val changed = sql.createUpdate(Book::class) {
            set(table.price, table.price + delta)
            set(table.version, table.version + 1)
            where(
                table.id eq id,
                table.version eq expectedVersion
            )
        }.execute()

        return changed == 1
    }

    fun search(
        sql: KSqlClient,
        name: String?,
        page: Int,
        size: Int
    ): Page<BookView> {
        require(page >= 0) { "page must be non-negative (zero-based)" }
        require(size > 0) { "size must be positive" }

        return sql.createQuery(Book::class) {
            where(table.name `like?` name)
            orderBy(table.name.asc(), table.id.asc())
            select(table.fetch(BookView::class))
        }.fetchPage(page, size)
    }
}
```

Jimmer 0.9.111 supports Kotlin `createUpdate` with expression-based assignments. Both increments happen atomically in one conditional update; bulk updates require the version predicate and increment explicitly, even with `@Version`. A stale version or missing ID affects zero rows and returns `false`; this API never inserts.

Search uses this release’s backticked `like?` operator to omit the name predicate when the argument is null. Ordering by name and then unique ID provides stable pagination, while `fetchPage` returns `Page<BookView>` with a total count. Generated model property extensions are available directly because this file shares their `example` package.
